/* SPDX-License-Identifier: GPL-2.0-or-later
 *
 * Builds the model viewer's SMOOTH MODEL: src/thirdparty/blender (Blender's
 * Weld and Subdivision Surface, the same C the game links) compiled to
 * WebAssembly with zig, written into ui/src/lib/mods/subsurf_wasm.js as
 * base64 so the window loads it with no file of its own.
 *
 *     node scripts/build-subsurf.js [path to zig]
 *
 * zig: the argument, UMK3_ZIG, or the toolchain the launcher downloads. The
 * generated file is committed, so a build without zig still has it. */
'use strict';
const { execFileSync } = require('child_process');
const fs = require('fs');
const os = require('os');
const path = require('path');

const ROOT = path.join(__dirname, '..', '..', '..');
const SRC = path.join(ROOT, 'src', 'thirdparty', 'blender');
const OUT = path.join(__dirname, '..', 'ui', 'src', 'lib', 'mods', 'subsurf_wasm.js');
const EXPORTS = ['umk_subsurf_new', 'umk_subsurf_eval', 'umk_subsurf_num_verts', 'umk_subsurf_pos',
    'umk_subsurf_uv', 'umk_subsurf_attr', 'umk_subsurf_num_tris', 'umk_subsurf_tris',
    'umk_subsurf_welded', 'umk_subsurf_free', 'umk_subsurf_set_sharp', 'umk_subsurf_sharp_edges',
    'umk_subsurf_set_fit',
    'malloc', 'free'];

function findZig() {
    if (process.argv[2]) return process.argv[2];
    if (process.env.UMK3_ZIG) return process.env.UMK3_ZIG;
    const base = process.platform === 'win32'
        ? path.join(process.env.LOCALAPPDATA || '', 'umk3-launcher', 'toolchain')
        : path.join(os.homedir(), '.local', 'share', 'umk3-launcher', 'toolchain');
    if (fs.existsSync(base))
        for (const d of fs.readdirSync(base)) {
            const z = path.join(base, d, process.platform === 'win32' ? 'zig.exe' : 'zig');
            if (fs.existsSync(z)) return z;
        }
    return null;
}

const zig = findZig();
if (!zig) {
    console.error('build-subsurf: no zig (pass its path or set UMK3_ZIG); keeping', path.relative(ROOT, OUT));
    process.exit(1);
}
const tmp = path.join(os.tmpdir(), 'umk3-subsurf.wasm');
execFileSync(zig, ['cc', '-target', 'wasm32-wasi', '-mexec-model=reactor', '-O2', '-std=gnu99', '-s',
    ...['umk3_subsurf.c', 'CCGSubSurf.c', 'CCGSubSurf_legacy.c', 'CCGSubSurf_util.c'].map(f => path.join(SRC, f)),
    '-I', SRC, '-I', path.join(SRC, 'shim'),
    ...EXPORTS.map(e => '-Wl,--export=' + e), '-o', tmp], { stdio: 'inherit' });
const b64 = fs.readFileSync(tmp).toString('base64');
fs.unlinkSync(tmp);
fs.writeFileSync(OUT,
    '/* SPDX-License-Identifier: GPL-2.0-or-later\n' +
    ' * Generated by launcher/app/scripts/build-subsurf.js from src/thirdparty/blender\n' +
    ' * (Blender\'s Weld and Subdivision Surface). Do not edit. */\n' +
    'export const SUBSURF_WASM = \'' + b64 + '\';\n');
console.log('build-subsurf:', path.relative(ROOT, OUT), Math.round(b64.length * 3 / 4 / 1024), 'KB of wasm');
